import {Market,COMPANIES} from './market.mjs';
const $=id=>document.getElementById(id),money=n=>n.toLocaleString('en-US',{style:'currency',currency:'USD'}),pct=n=>`${n.toFixed(2)}%`,time=n=>`${Math.floor(n/60)}:${String(n%60).padStart(2,'0')}`;
const market=new Market();let selected=0,focused=false;
$('company').innerHTML=COMPANIES.map((c,i)=>`<option value="${i}">${c.symbol} · ${c.name}</option>`).join('');
function focus(){focused=!focused;$('room').hidden=focused;$('focus').hidden=!focused;$('desk-toggle').textContent=focused?'Leave desk · E':'Use desk · E';render();}
$('desk-toggle').onclick=focus;$('interact').onclick=focus;
document.addEventListener('keydown',e=>{if(e.code==='KeyE'&&!['INPUT','SELECT','TEXTAREA'].includes(e.target.tagName))focus();});
$('dismiss').onclick=()=>{$('guidance').hidden=true;};
$('company').onchange=()=>{selected=Number($('company').value);render();};
for(const id of ['quantity','side'])$(id).addEventListener('input',preview);
$('open').onclick=()=>{market.open();$('message').textContent='Market open. Trading is optional.';render();};
$('next').onclick=()=>{market.nextDay();$('message').textContent='Account carried forward. Read the new brief before opening.';render();};
$('restart').onclick=()=>{try{market.restart(Number($('seed').value));$('message').textContent='Scenario reset: $10,000 and no positions.';render();}catch(e){$('message').textContent=e.message;}};
$('submit').onclick=()=>{const result=market.order(selected,$('side').value,$('quantity').value);$('message').textContent=result.error||`Filled ${result.quantity} ${COMPANIES[selected].symbol} at ${money(result.price)} · ${time(market.second)}.`;render();};
function preview(){const p=market.preview(selected,$('side').value,$('quantity').value);$('preview').textContent=p.error||`Estimated fill ${money(p.price)} · ${$('side').value==='buy'?'Cost':'Proceeds'} ${money(p.total)} · Cash after ${money(p.cash)} · Company exposure ${pct(p.exposure)} of post-trade midpoint equity. Quotes move until execution.`;$('submit').disabled=market.phase!=='trading';}
function timeline(){return market.timeline.map(e=>e.type==='execution'?`<article><strong>${time(e.second)} · ${e.side.toUpperCase()} ${e.quantity} ${e.symbol}</strong><p>Actual fill ${money(e.price)} · ${money(e.total)}</p></article>`:`<article><strong>${time(e.second)} · ${e.type==='earnings'?'Company announcement':'Market event'}</strong><p>${e.text}</p><p>Recorded event impulse: ${e.effects.map(x=>`${x.symbol} ${pct(x.fraction*100)}`).join(' / ')}.</p></article>`).join('')||'<p class="muted">No announcements or executions yet. Company news at 1:00; market survey at 2:00.</p>';}
function render(){
 $('status').textContent=`Day ${market.day} · ${market.phase.toUpperCase()} · ${market.phase==='trading'?time(180-market.second)+' remaining':time(market.second)}`;
 $('account').innerHTML=`<strong>Equity ${money(market.equity)}</strong><br>Cash ${money(market.cash)} · Today ${money(market.review.daily)} (${pct(market.review.percent)})<br><small>Holdings valued at bid/ask midpoint</small>`;
 const target=COMPANIES[market.target];
 $('brief').innerHTML=`<h2>Morning brief · Day ${market.day}</h2><p><strong>Will ${target.name} beat expected earnings of ${money(market.expected)} per share?</strong></p><p>• Harbor sells essentials; demand is relatively steady.<br>• Forge depends on capital spending; today’s economy survey may change its outlook.<br>• Lumen’s growth valuation is sensitive to earnings surprises.</p><p><strong>Calendar:</strong> 1:00 ${target.symbol} earnings (expected ${money(market.expected)}/share). 2:00 capital spending survey. Close at 3:00. Results are unknown before publication.</p><p class="muted">Decide what supports your view, how much you could lose, and which news would change your mind. No trade is required.</p>`;
 $('companies').innerHTML=COMPANIES.map((c,i)=>{const q=market.quote(i);return `<article><strong>${c.symbol} · ${c.name}</strong><p>${c.description}</p><p>Previous close ${money(market.openPrices[i])} · Mid ${money(q.mid)}<br>Bid ${money(q.bid)} / Ask ${money(q.ask)}</p></article>`;}).join('');
 $('portfolio').innerHTML=market.positions.map((p,i)=>`<article><strong>${COMPANIES[i].symbol} · ${p.quantity} shares</strong><p>Average cost ${money(p.quantity?p.basis/p.quantity:0)} · Basis ${money(p.basis)}<br>Midpoint value ${money(p.quantity*market.prices[i])}<br>Unrealized ${money(market.unrealized(i))}<br>Realized to date ${money(p.realized)}</p></article>`).join('');
 $('news').innerHTML=timeline();$('open').hidden=market.phase!=='preparation';$('next').hidden=market.phase!=='review';$('review').hidden=market.phase!=='review';
 if(market.phase==='review'){
 const r=market.review;$('review').innerHTML=`<h2>Closing review · Day ${market.day}</h2><p>Opening equity ${money(r.opening)} → Closing equity ${money(r.closing)}<br><strong>Daily result ${money(r.daily)} (${pct(r.percent)})</strong></p><p>Today’s realized ${money(r.companies.reduce((s,c)=>s+c.realized,0))} + change in unrealized ${money(r.companies.reduce((s,c)=>s+c.changeInUnrealized,0))} = daily result. Unrealized at close ${money(r.companies.reduce((s,c)=>s+c.unrealized,0))}. Prior-day unrealized is excluded from today’s gain.</p><table><thead><tr><th>Company</th><th>Today realized</th><th>Close unrealized</th><th>Δ unrealized</th><th>Daily result</th></tr></thead><tbody>${r.companies.map(c=>`<tr><td>${c.symbol}</td><td>${money(c.realized)}</td><td>${money(c.unrealized)}</td><td>${money(c.changeInUnrealized)}</td><td>${money(c.daily)}</td></tr>`).join('')}</tbody></table><p>Largest position: ${r.largest.symbol}, ${r.largest.quantity} shares, ${money(r.largest.value)} at ${time(r.largest.second)}. Measured by maximum midpoint dollar value, checked after every fill and simulation second, including opening holdings.</p><h3>Facts and interpretation</h3><p>${COMPANIES.map((c,i)=>`${c.symbol} midpoint ${money(market.openPrices[i])} → ${money(market.prices[i])} (${pct((market.prices[i]/market.openPrices[i]-1)*100)}).`).join(' ')}</p><p>The timeline records the exact earnings surprise and simulated price impulse, plus the survey impulse. Ordinary seeded fluctuations also moved quotes. News may support a view; it does not explain every price movement. Buying at ask and selling at bid incurs the spread even if midpoint prices do not move.</p><h3>Event & execution timeline</h3>${timeline()}`;
 }
 preview();chart();
}
function chart(){const ctx=$('chart').getContext('2d'),c=COMPANIES[selected],values=market.phase==='preparation'?market.closes[selected]:market.histories[selected];$('chart-title').textContent=`${c.symbol} · ${market.phase==='preparation'?'Recent closing history':'Intraday midpoint'}`;$('history-label').textContent=`${market.phase==='preparation'?'Five prior closes and current previous close; research context.':'One sample per simulation second.'} Range ${money(Math.min(...values))}–${money(Math.max(...values))}.`;ctx.clearRect(0,0,700,150);const min=Math.min(...values),range=Math.max(...values)-min||1;ctx.strokeStyle='#86e4bf';ctx.lineWidth=2;ctx.beginPath();values.forEach((p,i)=>{const x=10+i/Math.max(1,values.length-1)*680,y=135-(p-min)/range*120;i?ctx.lineTo(x,y):ctx.moveTo(x,y);});ctx.stroke();}
// Fixed isometric voxel furniture: no downloaded assets or external account data.
const ctx=$('desk').getContext('2d');function box(x,y,w,d,h,color){const P=(a,b,z)=>[600+(a-b)*29,220+(a+b)*14-z*25],poly=(points,fill)=>{ctx.fillStyle=fill;ctx.beginPath();points.forEach((p,i)=>i?ctx.lineTo(...p):ctx.moveTo(...p));ctx.closePath();ctx.fill();ctx.strokeStyle='#142432';ctx.stroke();};poly([P(x,y,h),P(x+w,y,h),P(x+w,y+d,h),P(x,y+d,h)],color);poly([P(x,y,h),P(x,y+d,h),P(x,y+d,0),P(x,y,0)],'#365164');poly([P(x,y+d,h),P(x+w,y+d,h),P(x+w,y+d,0),P(x,y+d,0)],'#223848');}
for(let x=-8;x<9;x++)for(let y=-4;y<9;y++)box(x,y,1,1,0,(x+y)%2?'#223849':'#2b4252');box(-4,0,9,4,3,'#ac845c');for(const x of [-3,0,3]){box(x,.5,2,.5,5,'#7abfae');box(x+.2,.2,1.6,.2,4.7,'#326c78');}box(0,5,3,2,1.5,'#567b8c');box(-6,0,1,1,3,'#7eb183');box(4,3,1,1,3.5,'#d7b88d');
let last=performance.now(),accumulator=0;setInterval(()=>{const now=performance.now();if(market.phase==='trading'){accumulator+=now-last;while(accumulator>=1000&&market.phase==='trading'){market.tick();accumulator-=1000;}render();}else accumulator=0;last=now;},100);
render();
